import random

import pygame

CELL = 20
COLS = 30
ROWS = 20
BAR_HEIGHT = 40

BLACK = (18, 18, 18)
GRID = (32, 32, 32)
WHITE = (240, 240, 240)
GRAY = (130, 130, 130)
GREEN = (0, 200, 80)
DARK_GREEN = (0, 130, 50)
RED = (220, 60, 60)

DIFFICULTIES = {"Easy": 6, "Medium": 10, "Hard": 15, "Insane": 22}


class Snake:
    def __init__(self):
        self.body = [(COLS // 2, ROWS // 2)]
        self.direction = (1, 0)
        self.pending_growth = 0

    def turn(self, direction):
        if (direction[0] * -1, direction[1] * -1) != self.direction:
            self.direction = direction

    def step(self):
        head = self.body[0]
        new_head = (head[0] + self.direction[0], head[1] + self.direction[1])
        if not (0 <= new_head[0] < COLS and 0 <= new_head[1] < ROWS):
            return False
        blocked = self.body if self.pending_growth else self.body[:-1]
        if new_head in blocked:
            return False
        self.body.insert(0, new_head)
        if self.pending_growth:
            self.pending_growth -= 1
        else:
            self.body.pop()
        return True

    def grow(self):
        self.pending_growth += 1


class Game:
    def __init__(self):
        self.width = COLS * CELL
        self.height = ROWS * CELL
        self.screen = pygame.display.set_mode((self.width, self.height + BAR_HEIGHT))
        pygame.display.set_caption("Snake")
        self.clock = pygame.time.Clock()
        self.font = pygame.font.SysFont("consolas", 20)
        self.big_font = pygame.font.SysFont("consolas", 36, bold=True)
        self.speed = DIFFICULTIES["Medium"]
        self.difficulty_name = "Medium"
        self.reset()

    def reset(self):
        self.snake = Snake()
        self.score = 0
        self.alive = True
        self.won = False
        self.food = self.spawn_food()

    def spawn_food(self):
        free = [(x, y) for x in range(COLS) for y in range(ROWS)
                if (x, y) not in self.snake.body]
        return random.choice(free) if free else None

    def choose_difficulty(self):
        options = list(DIFFICULTIES)
        selected = options.index(self.difficulty_name)
        while True:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    return None
                if event.type == pygame.KEYDOWN:
                    if event.key in (pygame.K_UP, pygame.K_w):
                        selected = (selected - 1) % len(options)
                    elif event.key in (pygame.K_DOWN, pygame.K_s):
                        selected = (selected + 1) % len(options)
                    elif event.key in (pygame.K_RETURN, pygame.K_SPACE):
                        return options[selected]
                    elif event.key == pygame.K_ESCAPE:
                        return None
            self.draw_menu(options, selected)
            self.clock.tick(30)

    def draw_menu(self, options, selected):
        self.screen.fill(BLACK)
        title = self.big_font.render("SNAKE", True, GREEN)
        self.screen.blit(title, (self.width // 2 - title.get_width() // 2, 50))
        for i, name in enumerate(options):
            color = GREEN if i == selected else GRAY
            text = self.font.render(name, True, color)
            self.screen.blit(text, (self.width // 2 - text.get_width() // 2, 130 + i * 34))
        hint = self.font.render("Up/Down: choose   Enter: start   Esc: quit", True, GRAY)
        self.screen.blit(hint, (self.width // 2 - hint.get_width() // 2, self.height - 40))
        pygame.display.flip()

    def handle_input(self):
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                return False
            if event.type == pygame.KEYDOWN:
                if event.key in (pygame.K_UP, pygame.K_w):
                    self.snake.turn((0, -1))
                elif event.key in (pygame.K_DOWN, pygame.K_s):
                    self.snake.turn((0, 1))
                elif event.key in (pygame.K_LEFT, pygame.K_a):
                    self.snake.turn((-1, 0))
                elif event.key in (pygame.K_RIGHT, pygame.K_d):
                    self.snake.turn((1, 0))
                elif event.key == pygame.K_ESCAPE:
                    return False
        return True

    def update(self):
        if not self.snake.step():
            self.alive = False
            return
        if self.snake.body[0] == self.food:
            self.score += 1
            self.snake.grow()
            self.food = self.spawn_food()
            if self.food is None:
                self.won = True
                self.alive = False

    def draw(self):
        self.screen.fill(BLACK)
        for x in range(0, self.width, CELL):
            pygame.draw.line(self.screen, GRID, (x, 0), (x, self.height))
        for y in range(0, self.height, CELL):
            pygame.draw.line(self.screen, GRID, (0, y), (self.width, y))
        if self.food is not None:
            pygame.draw.rect(self.screen, RED,
                             (self.food[0] * CELL, self.food[1] * CELL, CELL, CELL))
        for i, (x, y) in enumerate(self.snake.body):
            color = DARK_GREEN if i == 0 else GREEN
            pygame.draw.rect(self.screen, color, (x * CELL, y * CELL, CELL, CELL))
        pygame.draw.rect(self.screen, (40, 40, 40),
                         (0, self.height, self.width, BAR_HEIGHT))
        info = f"Score: {self.score}    Difficulty: {self.difficulty_name}"
        text = self.font.render(info, True, WHITE)
        self.screen.blit(text, (10, self.height + 10))
        pygame.display.flip()

    def draw_game_over(self):
        overlay = pygame.Surface((self.width, self.height))
        overlay.set_alpha(180)
        overlay.fill(BLACK)
        self.screen.blit(overlay, (0, 0))
        title = "YOU WIN!" if self.won else "GAME OVER"
        lines = [
            self.big_font.render(title, True, GREEN if self.won else RED),
            self.font.render(f"Final Score: {self.score}", True, WHITE),
            self.font.render("Enter: play again    Esc: quit", True, GRAY),
        ]
        for i, text in enumerate(lines):
            self.screen.blit(text, (self.width // 2 - text.get_width() // 2, 60 + i * 44))
        pygame.display.flip()

    def game_over_screen(self):
        while True:
            for event in pygame.event.get():
                if event.type == pygame.QUIT:
                    return False
                if event.type == pygame.KEYDOWN:
                    if event.key in (pygame.K_RETURN, pygame.K_SPACE):
                        return True
                    if event.key == pygame.K_ESCAPE:
                        return False
            self.draw_game_over()
            self.clock.tick(30)

    def run(self):
        difficulty = self.choose_difficulty()
        if difficulty is None:
            return
        self.difficulty_name = difficulty
        self.speed = DIFFICULTIES[difficulty]
        self.reset()
        running = True
        move_timer = 0.0
        while running:
            move_timer += self.clock.tick(60) / 1000.0
            running = self.handle_input()
            if running and self.alive and move_timer >= 1.0 / self.speed:
                move_timer = 0.0
                self.update()
            self.draw()
            if not self.alive:
                running = self.game_over_screen()
                if running:
                    self.reset()
                    move_timer = 0.0
